import "core-js/modules/es.array.push.js";
/*eslint-disable*/
import { list_users_for_tickets, get_user_ticket_details } from "@/graphql/queries.js";
import { assign_tickets } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import TicketAssign from "@/components/TicketManagement/AllDialogs/TicketAssign.vue";
import SnackBar from "@/components/SnackBar.vue";
var axios = require("axios");
export default {
  props: {
    claimDialog: Boolean,
    rowInfo: Object
  },
  components: {
    SnackBar,
    TicketAssign
  },
  data() {
    return {
      panel: [0],
      focus: "",
      type: "day",
      typeToLabel: {
        day: "Day",
        month: "Month",
        week: "Week"
      },
      dailyConfig: {
        minTime: "10:00:00",
        // 10:00 AM
        maxTime: "23:00:00"
      },
      selectedEvent: {},
      selectedElement: null,
      selectedOpen: false,
      events: [],
      colors: ["teal", "orange", "red lighten-1"],
      // names: [],
      height: 0,
      height2: 0,
      adminHeaders: [
      // {
      //   text: "Profile",
      //   value: "user_profile_pic_url",
      //   sortable: false,
      // },
      {
        text: "Name",
        value: "full_user_name",
        sortable: false
      }, {
        text: "Contact Number",
        value: "user_full_contact_number",
        sortable: false
      }],
      loading: false,
      assignDialog: false,
      timeSlotInfo: {},
      dragEvent: null,
      dragStart: null,
      createEvent: null,
      createStart: null,
      extendOriginal: null,
      fixed: false,
      teamData: [],
      tableLoading: false,
      valueSelected: false,
      rowData: {},
      loading1: false,
      SnackBarComponent: {},
      userTicketDetials: [],
      names: [],
      slotAvailabilityCheck: 0,
      checkbox: false,
      privatePublicSongs: [],
      componentCheck: 0,
      timeslotsData: {},
      dateChangeCheck: false,
      getDateValaue: "",
      previouscheck: false
    };
  },
  watch: {
    claimDialog: {
      async handler() {
        if (this.claimDialog == true) {
          this.height = window.innerHeight - 220;
          this.height2 = window.innerHeight - 50;
          this.teamData = [];
          this.slotAvailabilityCheck = false;
          this.valueSelected = false;
          this.checkbox = false;
          this.panel = [0];
          if (this.rowInfo.media_keys != undefined && this.rowInfo.media_keys.length != 0) {
            await this.check_private_public_urls();
          }
          await this.fetch_user_list();
        }
      },
      immediate: true
    }
  },
  mounted() {
    this.$refs.calendar.checkChange();
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.valueSelected = false;
      this.teamData = [];
    },
    sucess_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.assignDialog = false;
      this.$emit("onsuccess", "completed");
      this.$emit("clicked", 0);
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    validate_assign_check() {
      this.componentCheck = 1;
      this.assignDialog = true;
    },
    async check_private_public_urls() {
      this.privatePublicSongs = [];
      for (const url of this.rowInfo.media_keys) {
        try {
          const response = await axios.head(url);
          if (response.status === 200) {
            this.privatePublicSongs.push(url);
          }
        } catch (error) {
          if (error.response && error.response.status === 403) {
            this.fetch_presigned(url);
          } else {}
        }
      }
    },
    fetch_presigned(url) {
      var self = this;
      var response = self.$store.getters.GetOrgDetails;
      var s3Bucket = new AWS.S3({
        region: response.s3_details.region,
        accessKeyId: response.s3_details.access_key,
        secretAccessKey: response.s3_details.secret_key,
        signatureVersion: "v4"
      });
      var params = {
        Bucket: response.s3_details.bucket_name,
        Key: "tickets/" + url.split("tickets/")[1],
        Expires: 60000 * 5
      };
      var url = s3Bucket.getSignedUrl("getObject", params);
      this.privatePublicSongs.push(url);
    },
    handle_row_click(value) {
      this.slotAvailabilityCheck = false;
      this.valueSelected = false;
      this.rowData = value;
      this.dateChangeCheck = false;
      this.previouscheck = false;
      this.fetch_user_ticket_details(value);
    },
    fetch_value(val, valueCheck) {
      const d = new Date(parseInt(val * 1000));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      var dateValue = (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
      var timeValue = d.toLocaleString([], {
        hour: "2-digit",
        minute: "2-digit",
        hour12: true
      });
      const concatDateTime = dateValue + " " + timeValue;
      if (valueCheck == "time") {
        return timeValue;
      } else {
        return concatDateTime;
      }
    },
    async fetch_user_ticket_details(value) {
      // var data = this.$store.getters.GetUserObj;

      try {
        let result = await API.graphql(graphqlOperation(get_user_ticket_details, {
          input: {
            user_id: value.user_id,
            action_type: this.get_type(this.type),
            ticket_id: this.rowInfo.ticket_id,
            today_date: this.type == "day" ? this.fetch_current_date1() : undefined,
            assigned_month: this.type == "month" ? this.get_current_month() : undefined,
            offset: new Date().getTimezoneOffset() * 60
          }
        }));
        this.userTicketDetials = [];
        var response = JSON.parse(result.data.get_user_ticket_details);
        this.timeslotsData = response;
        this.valueSelected = true;
        this.slotAvailabilityCheck = response.slot_available;
        if (response.Status == "SUCCESS") {
          this.update_range(response);
        } else {
          this.events = [];
          this.tableLoading = false;
        }
      } catch (error) {
        // this.tableLoading = false;
      }
    },
    get_current_month() {
      const currentDate = new Date();
      const year = currentDate.getFullYear();
      const month = String(currentDate.getMonth() + 1).padStart(2, "0"); // Months are zero-indexed, so we add 1
      const formattedDate = `${year}-${month}`;
      return formattedDate;
    },
    get_type(val) {
      var data = "";
      if (val == "day") {
        data = "TODAY";
      } else if (val == "week") {
        data = "WEEKLY";
      } else if (val == "month") {
        data = "MONTHLY";
      }
      return data;
    },
    async fetch_user_list() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_users_for_tickets, {
          input: {
            organization_id: data.organization.organization_id,
            today_date: await this.fetch_current_date()
          }
        }));
        this.teamData = [];
        var response = JSON.parse(result.data.list_users_for_tickets);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.teamData = response.data;

          // console.log(this.teamData);
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
      }
    },
    fetch_current_date() {
      const currentDate = new Date();
      const year = currentDate.getFullYear().toString().padStart(4, "0");
      const month = (currentDate.getMonth() + 1).toString().padStart(2, "0"); // Months are zero-based
      const day = currentDate.getDate().toString().padStart(2, "0");
      const formattedDate = `${year}${month}${day}`;
      return formattedDate;
    },
    fetch_current_date1() {
      if (this.dateChangeCheck == true) {
        return this.getDateValaue;
      } else {
        const currentDate = new Date();
        const year = currentDate.getFullYear().toString().padStart(4, "0");
        const month = (currentDate.getMonth() + 1).toString().padStart(2, "0"); // Months are zero-based
        const day = currentDate.getDate().toString().padStart(2, "0");
        const formattedDate = `${year}-${month}-${day}`;
        return formattedDate;
      }
    },
    viewDay({
      date
    }) {
      // console.log(date);
      this.focus = date;
      this.type = "day";
    },
    setToday() {
      this.focus = "";
    },
    prev() {
      this.$refs.calendar.prev();
      this.$nextTick(() => {
        this.dateChangeCheck = true;
        this.getDateValaue = this.$refs.calendar.lastEnd.date;
        if (new Date().toISOString().split("T")[0] >= this.getDateValaue) {
          this.fetch_user_ticket_details(this.rowData);
        }
      });
    },
    next() {
      this.$refs.calendar.next();
      this.$nextTick(() => {
        this.dateChangeCheck = true;
        this.getDateValaue = this.$refs.calendar.lastEnd.date;
        this.fetch_user_ticket_details(this.rowData);
      });
    },
    showEvent({
      nativeEvent,
      event
    }) {
      const open = () => {
        this.selectedEvent = event;
        this.selectedElement = nativeEvent.target;
        requestAnimationFrame(() => requestAnimationFrame(() => this.selectedOpen = true));
      };
      if (this.selectedOpen) {
        this.selectedOpen = false;
        requestAnimationFrame(() => requestAnimationFrame(() => open()));
      } else {
        open();
      }
      nativeEvent.stopPropagation();
    },
    getEventColor(event) {
      return event.color;
    },
    update_range(value) {
      // console.log(value);
      const events = [];
      for (let i = 0; i < value.data.length; i++) {
        events.push({
          name: value.data[i].ticket_no_id,
          start: new Date(value.data[i].start_time * 1000),
          end: new Date(value.data[i].end_time * 1000),
          color: this.colors[this.rnd(0, this.colors.length - 1)],
          timed: true
        });
      }
      this.events = events;
    },
    rnd(a, b) {
      return Math.floor((b - a + 1) * Math.random()) + a;
    }
  }
};
